// TH16 v1.00a Extra (st07) MainSub07: two 20-enemy ECir01 rings, 600 frames apart.
// Source: st07.ecl.txt MainSub07 1358-1384 (entry), ECir01 67-104, ECir01_at 106-129.
// Source time base: instruction time T runs at world = base + T; wait(n) adds n to base.
// MainSub07's create loops stay on script time 0 (all 20 children of a ring are created
// in the same frame); the two wait(600) then put ring B at source frame 600 and the
// sub's return at 1200.
const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// TH16 type 8 = TH16_RICE (row base 480), colour 2 (bullet-types.md).
const TH16_RICE: int = 480;

// ECir01_at (106-129): one stream per enemy, one bullet every 5 frames, base angle
// advancing 0.087266 rad (5deg) per shot, 400 shots at most.
// Source emitter: etAim(0,3) fixed ring, etCount(0,1,1) -> delta 0.17453292 is inert;
// etSpeed(0,1.5,1.0) with one layer -> 1.5 px/frame.
// etEx(0,0,2,1,...) is ANIM: birth animation itself is omitted, but its entry shift
// position -= 4*velocity = -6 px along the bullet's own angle is kept via sh_dist.
async sub ecir_at(dir: angle) {
    wait(10);
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx);
    for k in 0..400 {
        // %A = %F2 + 0.087266*k ; 5deg = 65536/72 BAM.
        sh_angle(0, (dir as int + (k * 65536) / 72) as angle, 0deg);
        sh_fire(0);
        wait(5);
    }
}

// ECir01 (67-104). dir is the inherited F2 snapshot of the parent.
async sub ecir_main(dir: angle) {
    set_invuln(65535);
    // setHurtbox(24,24) -> circle radius 12 ; setHitbox(16,16) -> radius 8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // flagSet(15)/flagClear(15): body contact off during the 60-frame birth stage.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // moveVel(F2,0) then moveVelTime(60,1,F2,1.9): accelerate outward to 1.9 px/frame.
    move_vel(0, dir, 0fx, EASE_LINEAR);
    move_vel(60, dir, 1.9fx, EASE_QUAD_IN);
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn ecir_at(dir);
    wait(60);
    // moveVel(F2,0) at source frame 120: stop (angle unchanged).
    move_vel(0, dir, 0fx, EASE_LINEAR);
    // "+200:" label is script time 200; two preceding wait(60) pushed base to 120, so
    // the reverse phase starts 200 frames after the stop (source frame 320).
    wait(200);
    // moveSpeedTime(120,1,-2.0) : quadratic-in ramp from 0 to -2 over 120 frames.
    // moveAngleTime(600,7,0.0017453292) : mode 7 adds 0.1deg per frame for 600 frames.
    // Both run on the same polar velocity slots; drive them explicitly per frame so the
    // angle update cannot cancel the speed ramp (0.1deg = 65536/3600 BAM).
    var spd: fx = 0fx;
    for k in 1..601 {
        if k <= 120 {
            var u: fx = (k as fx) / 120fx;
            spd = 0fx - 2fx * u * u;
        }
        move_vel(0, (dir as int + (k * 65536) / 3600) as angle, spd, EASE_LINEAR);
        wait(1);
    }
    // Source keeps the enemy alive in a 1000-frame loop; it leaves by off-screen cull.
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Ring A: F2 = 0, -0.349066, ... (20deg steps, one child per step, same frame).
    for a_i in 0..20 {
        _ = spawn_enemy(0fx, 224fx, 300, 0, 0, 0,
                        ecir_main((0 - (a_i * 65536) / 18) as angle));
    }
    wait(600);
    // Ring B: F2 = 0, +0.349066, ... after the source's first wait(600).
    for b_i in 0..20 {
        _ = spawn_enemy(0fx, 224fx, 300, 0, 0, 0,
                        ecir_main(((b_i * 65536) / 18) as angle));
    }
    wait(600);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
